     1→/**
     2→ * FKUserMenu - User profile menu with logout functionality
     3→ * Displays user avatar, name, role and logout button
     4→ */
     5→import React, { useState } from 'react';
     6→import {
     7→  Box,
     8→  IconButton,
     9→  Menu,
    10→  MenuItem,
    11→  Avatar,
    12→  Typography,
    13→  Divider,
    14→  ListItemIcon,
    15→  CircularProgress,
    16→  Chip,
    17→} from '@mui/material';
    18→import {
    19→  Logout as LogoutIcon,
    20→  Person as PersonIcon,
    21→  ExpandMore as ExpandMoreIcon,
    22→} from '@mui/icons-material';
    23→import { useNavigate } from 'react-router-dom';
    24→import { useAuth } from '../../hooks/useAuth';
    25→
    26→const FKUserMenu: React.FC = () => {
    27→  const navigate = useNavigate();
    28→  const { user, userProfile, signOut, loading } = useAuth();
    29→  const [anchorEl, setAnchorEl] = useState<null | HTMLElement>(null);
    30→  const [isLoggingOut, setIsLoggingOut] = useState(false);
    31→
    32→  const open = Boolean(anchorEl);
    33→
    34→  const handleClick = (event: React.MouseEvent<HTMLElement>) => {
    35→    setAnchorEl(event.currentTarget);
    36→  };
    37→
    38→  const handleClose = () => {
    39→    setAnchorEl(null);
    40→  };
    41→
    42→  const handleLogout = async () => {
    43→    setIsLoggingOut(true);
    44→    handleClose();
    45→
    46→    try {
    47→      await signOut();
    48→      navigate('/login', { replace: true });
    49→    } catch (error) {
    50→      console.error('Error logging out:', error);
    51→      // Still navigate to login even if sign out fails
    52→      navigate('/login', { replace: true });
    53→    } finally {
    54→      setIsLoggingOut(false);
    55→    }
    56→  };
    57→
    58→  // Get user initials for avatar
    59→  const getInitials = (name: string): string => {
    60→    const parts = name.trim().split(' ');
    61→    if (parts.length >= 2) {
    62→      return `${parts[0][0]}${parts[1][0]}`.toUpperCase();
    63→    }
    64→    return name.substring(0, 2).toUpperCase();
    65→  };
    66→
    67→  // Get role label in Spanish
    68→  const getRoleLabel = (role: string): string => {
    69→    const roleLabels: Record<string, string> = {
    70→      admin: 'Administrador',
    71→      legal: 'Legal',
    72→      operations: 'Operaciones',
    73→      commercial: 'Comercial',
    74→      analyst: 'Analista',
    75→      mesa_control: 'Mesa de Control',
    76→      manager: 'Gerente',
    77→      user: 'Usuario',
    78→      cliente: 'Cliente',
    79→    };
    80→    return roleLabels[role] || role;
    81→  };
    82→
    83→  // Get user type badge color
    84→  const getUserTypeBadgeColor = (userType: string) => {
    85→    return userType === 'cliente' ? 'secondary' : 'primary';
    86→  };
    87→
    88→  // Only show loading spinner on initial load (when we don't have user data yet)
    89→  // Once we have user profile, keep showing it even if there's a background refresh
    90→  if (!user && loading) {
    91→    return (
    92→      <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
    93→        <CircularProgress size={24} sx={{ color: 'white' }} />
    94→      </Box>
    95→    );
    96→  }
    97→
    98→  // If we have user but no profile yet, show loading
    99→  if (user && !userProfile && loading) {
   100→    return (
   101→      <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
   102→        <CircularProgress size={24} sx={{ color: 'white' }} />
   103→      </Box>
   104→    );
   105→  }
   106→
   107→  // If we have user but profile failed to load, show minimal user info
   108→  if (user && !userProfile) {
   109→    return (
   110→      <Box>
   111→        <IconButton
   112→          size="small"
   113→          sx={{
   114→            gap: 1.5,
   115→            px: 1.5,
   116→            py: 0.5,
   117→            borderRadius: 2,
   118→            backgroundColor: 'rgba(255, 255, 255, 0.1)',
   119→            '&:hover': {
   120→              backgroundColor: 'rgba(255, 255, 255, 0.2)',
   121→            },
   122→          }}
   123→        >
   124→          <Avatar
   125→            sx={{
   126→              width: 36,
   127→              height: 36,
   128→              bgcolor: 'coral.main',
   129→              fontSize: '0.875rem',
   130→              fontWeight: 600,
   131→            }}
   132→          >
   133→            {user.email ? user.email.substring(0, 2).toUpperCase() : '??'}
   134→          </Avatar>
   135→          <Box sx={{ display: { xs: 'none', md: 'block' }, textAlign: 'left' }}>
   136→            <Typography
   137→              variant="body2"
   138→              sx={{ color: 'white', fontWeight: 600, lineHeight: 1.2 }}
   139→            >
   140→              {user.email || 'Usuario'}
   141→            </Typography>
   142→          </Box>
   143→        </IconButton>
   144→      </Box>
   145→    );
   146→  }
   147→
   148→  // TypeScript guard: if we reach here, userProfile must exist
   149→  if (!userProfile) {
   150→    return null;
   151→  }
   152→
   153→  return (
   154→    <Box>
   155→      {/* User Button */}
   156→      <IconButton
   157→        onClick={handleClick}
   158→        size="small"
   159→        sx={{
   160→          gap: 1.5,
   161→          px: 1.5,
   162→          py: 0.5,
   163→          borderRadius: 2,
   164→          backgroundColor: 'rgba(255, 255, 255, 0.1)',
   165→          '&:hover': {
   166→            backgroundColor: 'rgba(255, 255, 255, 0.2)',
   167→          },
   168→        }}
   169→        aria-controls={open ? 'user-menu' : undefined}
   170→        aria-haspopup="true"
   171→        aria-expanded={open ? 'true' : undefined}
   172→      >
   173→        <Avatar
   174→          sx={{
   175→            width: 36,
   176→            height: 36,
   177→            bgcolor: 'coral.main',
   178→            fontSize: '0.875rem',
   179→            fontWeight: 600,
   180→          }}
   181→        >
   182→          {getInitials(userProfile.full_name)}
   183→        </Avatar>
   184→        <Box sx={{ display: { xs: 'none', md: 'block' }, textAlign: 'left' }}>
   185→          <Typography
   186→            variant="body2"
   187→            sx={{ color: 'white', fontWeight: 600, lineHeight: 1.2 }}
   188→          >
   189→            {userProfile.full_name}
   190→          </Typography>
   191→          <Typography
   192→            variant="caption"
   193→            sx={{ color: 'rgba(255, 255, 255, 0.7)', lineHeight: 1 }}
   194→          >
   195→            {getRoleLabel(userProfile.role)}
   196→          </Typography>
   197→        </Box>
   198→        <ExpandMoreIcon sx={{ color: 'white', ml: 0.5 }} />
   199→      </IconButton>
   200→
   201→      {/* Dropdown Menu */}
   202→      <Menu
   203→        anchorEl={anchorEl}
   204→        id="user-menu"
   205→        open={open}
   206→        onClose={handleClose}
   207→        onClick={handleClose}
   208→        PaperProps={{
   209→          elevation: 4,
   210→          sx: {
   211→            minWidth: 280,
   212→            mt: 1.5,
   213→            borderRadius: 2,
   214→            '& .MuiMenuItem-root': {
   215→              borderRadius: 1,
   216→              mx: 1,
   217→              my: 0.5,
   218→            },
   219→          },
   220→        }}
   221→        transformOrigin={{ horizontal: 'right', vertical: 'top' }}
   222→        anchorOrigin={{ horizontal: 'right', vertical: 'bottom' }}
   223→      >
   224→        {/* User Info Header */}
   225→        <Box sx={{ px: 2, py: 2 }}>
   226→          <Box sx={{ display: 'flex', alignItems: 'center', gap: 2, mb: 1.5 }}>
   227→            <Avatar
   228→              sx={{
   229→                width: 48,
   230→                height: 48,
   231→                bgcolor: 'primary.main',
   232→                fontSize: '1.125rem',
   233→                fontWeight: 600,
   234→              }}
   235→            >
   236→              {getInitials(userProfile.full_name)}
   237→            </Avatar>
   238→            <Box sx={{ flex: 1 }}>
   239→              <Typography variant="subtitle1" sx={{ fontWeight: 600, lineHeight: 1.3 }}>
   240→                {userProfile.full_name}
   241→              </Typography>
   242→              <Typography variant="body2" color="text.secondary" sx={{ fontSize: '0.8125rem' }}>
   243→                {user?.email}
   244→              </Typography>
   245→            </Box>
   246→          </Box>
   247→
   248→          {/* User Type and Role Badges */}
   249→          <Box sx={{ display: 'flex', gap: 1, flexWrap: 'wrap' }}>
   250→            <Chip
   251→              label={userProfile.user_type === 'cliente' ? 'Cliente' : 'Funcionario'}
   252→              size="small"
   253→              color={getUserTypeBadgeColor(userProfile.user_type)}
   254→              sx={{ fontSize: '0.75rem', height: 24 }}
